export async function loadLatestOnSat(loaderId) {
  const sat = await fetch(`/r/inscription/${loaderId}`)
    .then(r => r.json())
    .then(j => j.sat);
  if (!sat) throw new Error(`sat not found for ${loaderId}`);
  const latestId = await fetch(`/r/sat/${sat}/at/-1`)
    .then(r => r.json())
    .then(j => j.id || loaderId);

  return import(`/content/${latestId}`);
}

// jsonLoader.js

export async function loadLatestConfig(jsonLoaderId) {
  const { sat } = await fetch(`/r/inscription/${jsonLoaderId}`).then(r => r.json());
  if (!sat) throw new Error(`sat not found for ${jsonLoaderId}`);

  const { id: latestId } = await fetch(`/r/sat/${sat}/at/-1`).then(r => r.json());
  const cfgId = latestId || jsonLoaderId;

  return fetch(`/content/${cfgId}`).then(r => r.json());
}

