  fn from_str(s: &str) -> Result<Self, Self::Err> {
    let (outpoint, offset) = s
      .rsplit_once(':')
      .ok_or_else(|| anyhow!("invalid satpoint: {s}"))?;

    Ok(SatPoint {
      outpoint: outpoint.parse()?,
      offset: offset.parse()?,
    })
  }
}

